//
//  Advanced Bloom with Compute Shaders
//  Native Metal Shader - Multi-pass HDR Bloom
//

#include <metal_stdlib>
using namespace metal;

struct Uniforms {
    float4x4 MVP;
    float4 OutputSize;
    float4 SourceSize;
    float4 OriginalSize;
    uint FrameCount;
    float threshold;
    float intensity;
    float radius;
    float soft_knee;
};

// MARK: - Compute Shader (Bright Pass)

kernel void bright_pass(
    texture2d<float, access::read> inputTexture [[texture(0)]],
    texture2d<float, access::write> outputTexture [[texture(1)]],
    constant Uniforms &uniforms [[buffer(0)]],
    uint2 gid [[thread_position_in_grid]]
)
{
    if (gid.x >= uint(uniforms.SourceSize.x) || gid.y >= uint(uniforms.SourceSize.y)) return;

    float4 color = inputTexture.read(gid);
    float luminance = dot(color.rgb, float3(0.2126, 0.7152, 0.0722));

    // Soft threshold
    float knee = uniforms.threshold * uniforms.soft_knee;
    float soft = luminance - uniforms.threshold + knee;
    soft = clamp(soft, 0.0, 2.0 * knee);
    soft = soft * soft / (4.0 * knee + 0.00001);

    float contribution = max(soft, luminance - uniforms.threshold);
    contribution /= max(luminance, 0.00001);

    outputTexture.write(color * contribution, gid);
}

// MARK: - Compute Shader (Gaussian Blur Horizontal)

kernel void blur_horizontal(
    texture2d<float, access::read> inputTexture [[texture(0)]],
    texture2d<float, access::write> outputTexture [[texture(1)]],
    constant Uniforms &uniforms [[buffer(0)]],
    uint2 gid [[thread_position_in_grid]]
)
{
    if (gid.x >= uint(uniforms.SourceSize.x) || gid.y >= uint(uniforms.SourceSize.y)) return;

    // Gaussian weights
    const int kernelSize = 5;
    const float weights[9] = {
        0.0162, 0.0540, 0.1216, 0.1945, 0.2270,
        0.1945, 0.1216, 0.0540, 0.0162
    };

    float4 result = float4(0.0);
    int offset = kernelSize / 2;

    for (int i = 0; i < kernelSize; i++) {
        int x = int(gid.x) + (i - offset);
        x = clamp(x, 0, int(uniforms.SourceSize.x) - 1);

        float4 sample = inputTexture.read(uint2(x, gid.y));
        result += sample * weights[i];
    }

    outputTexture.write(result, gid);
}

// MARK: - Compute Shader (Gaussian Blur Vertical)

kernel void blur_vertical(
    texture2d<float, access::read> inputTexture [[texture(0)]],
    texture2d<float, access::write> outputTexture [[texture(1)]],
    constant Uniforms &uniforms [[buffer(0)]],
    uint2 gid [[thread_position_in_grid]]
)
{
    if (gid.x >= uint(uniforms.SourceSize.x) || gid.y >= uint(uniforms.SourceSize.y)) return;

    const int kernelSize = 5;
    const float weights[9] = {
        0.0162, 0.0540, 0.1216, 0.1945, 0.2270,
        0.1945, 0.1216, 0.0540, 0.0162
    };

    float4 result = float4(0.0);
    int offset = kernelSize / 2;

    for (int i = 0; i < kernelSize; i++) {
        int y = int(gid.y) + (i - offset);
        y = clamp(y, 0, int(uniforms.SourceSize.y) - 1);

        float4 sample = inputTexture.read(uint2(gid.x, y));
        result += sample * weights[i];
    }

    outputTexture.write(result, gid);
}

// MARK: - Vertex Shader

struct VertexIn {
    float4 position [[attribute(0)]];
    float2 texCoord [[attribute(1)]];
};

struct VertexOut {
    float4 position [[position]];
    float2 texCoord;
};

vertex VertexOut main0(
    VertexIn in [[stage_in]],
    constant Uniforms &uniforms [[buffer(0)]]
)
{
    VertexOut out;
    out.position = uniforms.MVP * in.position;
    out.texCoord = in.texCoord;
    return out;
}

// MARK: - Fragment Shader (Composite)

fragment float4 fragment_main(
    VertexOut in [[stage_in]],
    texture2d<float> sourceTexture [[texture(0)]],
    texture2d<float> bloomTexture [[texture(1)]],
    constant Uniforms &uniforms [[buffer(0)]]
)
{
    constexpr sampler textureSampler(
        mag_filter::linear,
        min_filter::linear,
        address::clamp_to_edge
    );

    float4 original = sourceTexture.sample(textureSampler, in.texCoord);
    float4 bloom = bloomTexture.sample(textureSampler, in.texCoord);

    // Additive blending with intensity
    float4 result = original + bloom * uniforms.intensity;

    return result;
}

